class Solution { public int[][] rotateGrid(int[][] grid,int k){int rows=grid.length,cols=grid[0].length;for(int layer=0;layer<Math.min(rows,cols)/2;layer++){int top=layer,bottom=rows-1-layer,left=layer,right=cols-1-layer;List<int[]> positions=new ArrayList<>();for(int col=left;col<=right;col++)positions.add(new int[]{top,col});for(int row=top+1;row<=bottom;row++)positions.add(new int[]{row,right});for(int col=right-1;col>=left;col--)positions.add(new int[]{bottom,col});for(int row=bottom-1;row>top;row--)positions.add(new int[]{row,left});int[] values=new int[positions.size()];for(int i=0;i<values.length;i++){int[] position=positions.get(i);values[i]=grid[position[0]][position[1]];}int shift=k%values.length;for(int i=0;i<values.length;i++){int[] position=positions.get(i);grid[position[0]][position[1]]=values[(i+shift)%values.length];}}return grid;} }
